#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int iBegin, iEnd, iSum = 0;

    cout << "Begin Number: ";
    std::cin >> iBegin;

    cout << "End Number: ";
    std::cin >> iEnd;

    for (int i = iBegin; i <= iEnd; i++)
    {
        iSum += i;
    }

    cout << "Sum: " << iSum << endl;

    return 0;
}

