#include <iostream>

using std::cout;
using std::endl;

int main()
{
    for (int i = 1; i <= 4; i++)
    {
        for (int j = 0; j < 4 - i; j++)
        {
            cout << " ";
        }

        for (int j = 0; j < 2 * i - 1; j++)
        {
            cout << "*";
        }

        cout << endl;
    }

    return 0;
}
